-- pipeline/finish-run
-- Records how a run ended, with its counts and each outlet's result.
--
-- Parameters, with the example values used to render this file:
--   $1 = "succeeded"
--   $2 = 120
--   $3 = 14
--   $4 = 3
--   $5 = "[{\"slug\":\"example-news\",\"ok\":true,\"items\":20,\"new\":2}]"
--   $6 = null
--   $7 = "0199c8a0-0000-7000-8000-00000000000a"
--
-- Generated by `pnpm db:queries` from lib/db/queries/pipeline.ts. Do not edit by hand.

update "pipeline_runs"
set "status" = $1, "finished_at" = now(), "items_seen" = $2, "items_new" = $3, "candidates_new" = $4, "outlet_results" = $5, "error" = $6, "updated_at" = now()
where "pipeline_runs"."id" = $7;
